package in.foodcart.api; import in.foodcart.data.*; import in.foodcart.domain.*; import in.foodcart.service.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/vendor") public class VendorController {private final AuthService auth;private final VendorRepository vendors;private final MenuItemRepository items;private final MenuCategoryRepository categories;private final OrderRepository orders;private final CheckoutService checkout;public VendorController(AuthService a,VendorRepository v,MenuItemRepository i,MenuCategoryRepository c,OrderRepository o,CheckoutService co){auth=a;vendors=v;items=i;categories=c;orders=o;checkout=co;}private String owner(String h){return auth.actor(h,"VENDOR");}@GetMapping("/me") VendorEntity me(@RequestHeader("Authorization") String h){return vendors.findById(owner(h)).orElseThrow();}@PatchMapping("/me/status") VendorEntity status(@RequestHeader("Authorization") String h,@RequestBody Map<String,VendorStatus> body){VendorEntity v=vendors.findById(owner(h)).orElseThrow();v.status=body.get("status");v.updatedAt=Instant.now();return vendors.save(v);}@GetMapping("/orders") List<OrderEntity> orders(@RequestHeader("Authorization") String h){return orders.findByVendorIdOrderByCreatedAtDesc(owner(h));}@PatchMapping("/orders/{id}/status") OrderEntity orderStatus(@RequestHeader("Authorization") String h,@PathVariable String id,@RequestBody Map<String,OrderStatus> body){return checkout.status(owner(h),id,body.get("status"));}@PostMapping("/orders/{id}/reject") OrderEntity reject(@RequestHeader("Authorization") String h,@PathVariable String id,@RequestBody Map<String,String> body){OrderEntity o=checkout.status(owner(h),id,OrderStatus.REJECTED);o.rejectionReason=body.get("reason");o.rejectionNote=body.get("note");return orders.save(o);}@GetMapping("/dashboard/today") Map<String,Object> today(@RequestHeader("Authorization") String h){List<OrderEntity> all=orders.findByVendorIdOrderByCreatedAtDesc(owner(h));List<OrderEntity> now=all.stream().filter(o->o.createdAt.isAfter(Instant.now().minusSeconds(86400))).toList();long completed=now.stream().filter(o->o.status==OrderStatus.COMPLETED).count();return Map.of("totalOrders",now.size(),"completed",completed,"rejected",now.stream().filter(o->o.status==OrderStatus.REJECTED).count(),"inProgress",now.stream().filter(o->o.status==OrderStatus.ACCEPTED||o.status==OrderStatus.PREPARING||o.status==OrderStatus.READY).count(),"completedSales",now.stream().filter(o->o.status==OrderStatus.COMPLETED).map(o->o.total).reduce(java.math.BigDecimal.ZERO,java.math.BigDecimal::add));}@GetMapping("/menu") Map<String,Object> menu(@RequestHeader("Authorization") String h){String v=owner(h);return Map.of("categories",categories.findByVendorIdOrderBySortOrder(v),"items",items.findByVendorIdOrderBySortOrder(v));}@PostMapping("/menu/items") MenuItemEntity add(@RequestHeader("Authorization") String h,@RequestBody MenuItemEntity i){i.id=null;i.vendorId=owner(h);return items.save(i);}@PutMapping("/menu/items/{id}") MenuItemEntity edit(@RequestHeader("Authorization") String h,@PathVariable String id,@RequestBody MenuItemEntity update){MenuItemEntity i=items.findByIdAndVendorId(id,owner(h)).orElseThrow(()->new SecurityException("Item not found"));i.name=update.name;i.description=update.description;i.price=update.price;i.categoryId=update.categoryId;i.imageUrl=update.imageUrl;i.active=update.active;i.available=update.available;return items.save(i);}@PatchMapping("/menu/items/{id}/availability") MenuItemEntity availability(@RequestHeader("Authorization") String h,@PathVariable String id,@RequestBody Map<String,Boolean> body){MenuItemEntity i=items.findByIdAndVendorId(id,owner(h)).orElseThrow(()->new SecurityException("Item not found"));i.available=Boolean.TRUE.equals(body.get("available"));return items.save(i);}@PostMapping("/menu/categories") MenuCategoryEntity category(@RequestHeader("Authorization") String h,@RequestBody MenuCategoryEntity c){c.id=null;c.vendorId=owner(h);return categories.save(c);}}
